Lemma nullalign_and_1 : forall p, 0 < p -> p mod 8 = 0 -> Z.land (Z.b2z (0 <? p)) (Z.b2z (Z.land p 7 <? 1)) = 1.
Proof.
  intros p Hp Ha. rewrite land7_mod8, Ha. replace (0 <? p) with true by (symmetry; apply Z.ltb_lt; exact Hp). reflexivity.
Qed.

