Definition bcopy_post (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (tbp tep srp cbp src b : Z) (es : list mbe) (insz n x lo shi : Z) (bs : list byte) (m : mem) : machine_state -> Prop :=
  fun ms' => exists t0 t1 t2 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 m',
    ms' = MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (wz n) a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
             F (ret_pc ra) fc None m' (seg_rom bsegs)
    /\ munch (bcopyW lo sp b es insz n x) m m' /\ wmono bsegs m m' /\ mem_inv bsegs m'
    /\ stk bsegs m' lo (bv_unsigned sp)
    /\ rw_cells bsegs m' tbp [C8 (wz srp); C8 (wz (mb_mid_out b es insz x))]
    /\ rw_cells bsegs m' tep [C8 (wz srp); C8 (wz (b + 8))]
    /\ rw_cells bsegs m' srp (SrCells b (mb_mid_out b es insz x) (b + 8) (mb_outpos es insz) (mb_mid_outend es insz n))
    /\ rw_cells bsegs m' cbp [C8 (wz src); C8 (wz n)]
    /\ bytes_at bsegs m' src bs
    /\ AMBmid m' b es insz n x
    /\ ACONST m' /\ stack0 m' lo shi.

Definition bcopy_stmt : Prop := forall (tbp tep srp cbp src b : Z) (es : list mbe) (insz n x lo shi : Z) (bs : list byte)
    ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a5 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6
    (F : bvmap 5 word) fc (m : mem),
  AMBmid m b es insz n x -> mb_ok es insz -> 1 <= n -> insz + n <= 2^30 ->
  rw_cells bsegs m tbp [C8 (wz srp); C8 (wz (mb_mid_out b es insz x))] ->
  rw_cells bsegs m tep [C8 (wz srp); C8 (wz (b + 8))] ->
  rw_cells bsegs m srp (SrCells b (mb_mid_out b es insz x) (b + 8) (mb_outpos es insz) (mb_mid_outend es insz n)) ->
  rw_cells bsegs m cbp [C8 (wz src); C8 (wz n)] ->
  bytes_at bsegs m src bs -> zlength bs = n ->
  (src + n <= lo \/ bv_unsigned sp <= src) ->
  (tbp + 16 <= lo \/ bv_unsigned sp <= tbp) -> (tep + 16 <= lo \/ bv_unsigned sp <= tep) ->
  (srp + 40 <= lo \/ bv_unsigned sp <= srp) -> (cbp + 16 <= lo \/ bv_unsigned sp <= cbp) ->
  mb_off b (mb_put_es es insz n x) src n ->
  mb_off b (mb_put_es es insz n x) tbp 16 -> mb_off b (mb_put_es es insz n x) tep 16 ->
  mb_off b (mb_put_es es insz n x) srp 40 -> mb_off b (mb_put_es es insz n x) cbp 16 ->
  stk bsegs m lo (bv_unsigned sp) -> lo + MB_BCOPY_STACK <= bv_unsigned sp -> aceil <= lo ->
  bv_unsigned ra mod 2 = 0 ->
  mem_inv bsegs m ->
  (* [comment removed for export] *)
  bv_unsigned sp mod 16 = 0 -> ACONST m -> stack0 m lo shi -> bv_unsigned sp <= shi ->
  tbp mod 8 = 0 -> accessible m tbp 16 -> tep mod 8 = 0 -> accessible m tep 16 ->
  srp mod 8 = 0 -> accessible m srp 40 -> cbp mod 8 = 0 -> accessible m cbp 16 ->
  accessible m src n -> shvis m src (src + n) -> in_app_mem src (src + n) ->
  shvis m (fst (mb_b1 b es insz n x)) (fst (mb_b1 b es insz n x) + snd (mb_b1 b es insz n x)) ->
  shvis m (fst (mb_b2 b es insz n x)) (fst (mb_b2 b es insz n x) + snd (mb_b2 b es insz n x)) ->
  (* [comment removed for export] *)
  0 < tbp -> 0 < tep -> 0 < cbp -> 0 < srp -> 0 < src ->
  evt bsegs (bcopy_post ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc tbp tep srp cbp src b es insz n x lo shi bs m)
    (MS (mkR ra sp gp tp t0 t1 t2 s0 s1 a0 a1 (wz tbp) (wz tep) (wz cbp) a5 (Z_to_bv 64 (2^64 - 1)) a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
        F (Z_to_bv 64 P_A_BUFFER_COPY_MB) fc None m (seg_rom bsegs)).

