  stk bsegs m1 lo (bv_unsigned sp + -112) -> lo + MB_BCOPY_STACK <= bv_unsigned sp -> aceil <= lo ->
  bv_unsigned sp mod 16 = 0 -> mem_inv bsegs m1 -> ACONST m1 -> stack0 m1 lo shi -> bv_unsigned sp <= shi ->
  (* [comment removed for export] *)
  rw_cells bsegs m1 tep [C8 (Z_to_bv 64 srp); C8 (Z_to_bv 64 (b + 8))] ->
  rw_cells bsegs m1 srp [C8 (Z_to_bv 64 b); C8 (Z_to_bv 64 beg); C8 (Z_to_bv 64 (b + 8)); C8 (Z_to_bv 64 bpos); C8 (Z_to_bv 64 lpos)] ->
  rw_cells bsegs m1 (b + 8) [C8 (Z_to_bv 64 fst1); C8 (Z_to_bv 64 pe)] ->
  rw_cells bsegs m1 cur [C8 (Z_to_bv 64 nxt); C8 (Z_to_bv 64 prv)] ->
  rw_cells bsegs m1 (cur + 16) [C8 (Z_to_bv 64 sx)] ->
  rw_cells bsegs m1 ptr [CB (Z.to_nat k) jd] ->
  bytes_at bsegs m1 sc bsk -> length bsk = Z.to_nat k ->
  (* [comment removed for export] *)
  deref_res cur beg pe bpos lpos sx = (ptr, k) -> 1 <= k -> k <= r -> r <= 2^40 -> 0 <= c < 2^62 ->
  cur + 24 <= ptr -> ptr + k <= cur + 24 + sx ->
  1 <= lpos < 2^62 -> 0 <= bpos < 2^62 -> 0 <= sx < 2^62 -> 0 <= beg < 2^62 -> 0 <= pe < 2^62 -> 0 <= nxt < 2^62 ->
  AIMG_TOP <= cur -> cur + 24 + sx <= aceil -> AIMG_TOP <= b -> b + 64 <= aceil -> cur <> b + 8 ->
  (cur + 24 + sx <= b \/ b + 64 <= cur) ->
  (* [comment removed for export] *)
