  (tep + 16 <= cur \/ cur + 24 + sx <= tep) -> (srp + 40 <= cur \/ cur + 24 + sx <= srp) ->
  (tep + 16 <= b \/ b + 64 <= tep) -> (srp + 40 <= b \/ b + 64 <= srp) ->
  (sc + k <= lo \/ bv_unsigned sp <= sc) -> (sc + k <= ptr \/ ptr + k <= sc) -> 0 <= sc ->
  (* [comment removed for export] *)
  tep mod 8 = 0 -> accessible m1 tep 16 -> srp mod 8 = 0 -> accessible m1 srp 40 ->
  b mod 8 = 0 -> accessible m1 b 64 -> cur mod 8 = 0 -> accessible m1 cur (24 + sx) ->
  accessible m1 sc k -> shvis m1 sc (sc + k) -> in_app_mem sc (sc + k) ->
  shvis m1 ptr (ptr + k) -> aapp cur (24 + sx) ->
  (* [comment removed for export] *)
  0 < tep -> 0 < srp -> 0 < sc ->
  (* [comment removed for export] *)
