     munch [(lo, bv_unsigned sp); (ptr, ptr + k)]%Z m1 m2 -> wmono bsegs m1 m2 -> mem_inv bsegs m2 ->
     rw_cells bsegs m2 (bv_unsigned sp + -112) [CB 8 j0] ->
