     rw_cells bsegs m2 (bv_unsigned sp + -88) [C8 s9'; C8 s8'; C8 s7'; C8 s6'; C8 s5'; C8 s4'; C8 s3'; C8 s2'; C8 s1'; C8 s0'; C8 ra'] ->
     stk bsegs m2 lo (bv_unsigned sp + -112) ->
     rw_cells bsegs m2 ptr [CB (Z.to_nat k) bsk] -> bytes_at bsegs m2 sc bsk -> ACONST m2 ->
     evt bsegs Q (bc_st 0xc31d0 rax' (Z_to_bv 64 (bv_unsigned sp + -112)) gp tp y0 y1 y2 tep (k + c) (sc + k) (r + - k)
                        b0 b1 b2 b3 b4 b5 b6 b7 (Z_to_bv 64 k) s10 s11 y3 y4 y5 y6 F fc m2)) ->
