  rw_cells bsegs m tbp [C8 (Z_to_bv 64 srp); C8 (Z_to_bv 64 cur0)] ->
  rw_cells bsegs m cbp [C8 (Z_to_bv 64 src); C8 (Z_to_bv 64 n)] ->
  1 <= n <= 2^40 -> 0 <= srp < 2^64 -> 0 <= cur0 < 2^64 -> 0 <= src < 2^64 -> 0 < tep -> tep + 16 <= 2^47 ->
